#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Instr {
    std::string text;
    int dst, src1, src2;  // register numbers
    int latency;          // cycles until dst holds the result
};

// An in-order pipeline: it starts at most one instruction per cycle, in program order,
// and holds an instruction back until both its sources are ready.
int run(const std::vector<Instr>& program) {
    int ready[16] = {};  // the cycle each register's value is ready, 0 for values already there
    int last = -1;       // the cycle the previous instruction started
    int done = 0;
    for (const Instr& in : program) {
        int start = std::max({last + 1, ready[in.src1], ready[in.src2]});
        ready[in.dst] = start + in.latency;
        done = std::max(done, ready[in.dst]);
        last = start;
        std::cout << "  cycle " << start << ": " << in.text << '\n';
    }
    return done;
}

int main() {
    const int add = 4;  // a double add's latency
    // Registers 0 and 1 are running sums, 8 to 11 hold four prices already loaded.
    std::vector<Instr> one_sum = {
        {"s0 += p0", 0, 0, 8, add},
        {"s0 += p1", 0, 0, 9, add},
        {"s0 += p2", 0, 0, 10, add},
        {"s0 += p3", 0, 0, 11, add},
    };
    std::vector<Instr> two_sums = {
        {"s0 += p0", 0, 0, 8, add},
        {"s1 += p1", 1, 1, 9, add},
        {"s0 += p2", 0, 0, 10, add},
        {"s1 += p3", 1, 1, 11, add},
        {"s0 += s1", 0, 0, 1, add},
    };
    std::cout << "one sum\n";
    int cycles = run(one_sum);
    std::cout << "  done after " << cycles << " cycles\n";
    std::cout << "two sums\n";
    cycles = run(two_sums);
    std::cout << "  done after " << cycles << " cycles\n";
    return 0;
}

