// -O2
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

double sum_one(const double* p, std::size_t n) {  // one chain: each add waits for the last
    double s = 0;
    for (std::size_t i = 0; i < n; ++i) {
        s += p[i];
    }
    return s;
}

double sum_four(const double* p, std::size_t n) {  // four chains that never wait on each other
    double s0 = 0, s1 = 0, s2 = 0, s3 = 0;
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        s0 += p[i];
        s1 += p[i + 1];
        s2 += p[i + 2];
        s3 += p[i + 3];
    }
    for (; i < n; ++i) {  // the last few, when n isn't a multiple of 4
        s0 += p[i];
    }
    return (s0 + s1) + (s2 + s3);
}

int main() {
    const std::size_t n = 1'000'000;
    std::vector<double> sizes(n + 100);
    for (std::size_t i = 0; i < sizes.size(); ++i) {
        sizes[i] = 0.25 * (1 + i % 8);  // quarter lots, so every sum is exact
    }
    double one = 0, four = 0;
    auto start = std::chrono::steady_clock::now();
    for (int run = 0; run < 100; ++run) {
        one += sum_one(sizes.data() + run, n);  // a new window each run, so none can be skipped
    }
    auto middle = std::chrono::steady_clock::now();
    for (int run = 0; run < 100; ++run) {
        four += sum_four(sizes.data() + run, n);
    }
    auto stop = std::chrono::steady_clock::now();
    using ms = std::chrono::duration<double, std::milli>;
    // std::cout << ms(middle - start).count() << " ms, " << ms(stop - middle).count() << " ms\n";

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "one chain:   " << one << '\n';
    std::cout << "four chains: " << four << '\n';
    return 0;
}

