#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

// The sum of squared price moves, the top half of a variance: one chain.
double sum_sq_one(const double* r, std::size_t n) {
    double s = 0;
    for (std::size_t i = 0; i < n; ++i) {
        s += r[i] * r[i];
    }
    return s;
}

double sum_sq_two(const double* r, std::size_t n) {
    double s0 = 0, s1 = 0;
    std::size_t i = 0;
    for (; i + 2 <= n; i += 2) {
        s0 += r[i] * r[i];
        s1 += r[i + 1] * r[i + 1];
    }
    for (; i < n; ++i) {
        s0 += r[i] * r[i];
    }
    return s0 + s1;
}

int main() {
    std::size_t n = 0;
    std::cin >> n;
    std::vector<double> moves(n);
    for (std::size_t i = 0; i < n; ++i) {
        moves[i] = 0.25 * (static_cast<int>(i % 9) - 4);  // from -1.00 to +1.00 in quarter steps
    }
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "one chain:  " << sum_sq_one(moves.data(), n) << '\n';
    std::cout << "two chains: " << sum_sq_two(moves.data(), n) << '\n';
    return 0;
}

