#include <algorithm>
#include <cstdint>
#include <iostream>
#include <vector>

// Counts the wrong guesses of one 2-bit counter. States 0 and 1 guess "not taken",
// 2 and 3 guess "taken", and each outcome moves the state one step toward itself.
int mispredicts(const std::vector<bool>& outcomes) {
    int state = 2;
    int wrong = 0;
    for (bool taken : outcomes) {
        if ((state >= 2) != taken) {
            ++wrong;
        }
        if (taken && state < 3) {
            ++state;
        } else if (!taken && state > 0) {
            --state;
        }
    }
    return wrong;
}

int main() {
    const int n = 1000;
    std::vector<int> sizes(n);
    uint32_t x = 2024;  // the same "random" sizes on every run
    for (int& s : sizes) {
        x = x * 1664525u + 1013904223u;
        s = x >> 24;  // the top 8 bits: a size from 0 to 255
    }
    std::vector<int> sorted = sizes;
    std::sort(sorted.begin(), sorted.end());

    std::vector<bool> loop, in_order, shuffled;
    for (int i = 0; i < n; ++i) {
        loop.push_back(i + 1 < n);             // a loop's branch back: taken until the last trip
        in_order.push_back(sorted[i] >= 128);  // if (size >= 128) on sorted sizes
        shuffled.push_back(sizes[i] >= 128);   // the same test in arrival order
    }
    std::cout << "loop branch:    " << mispredicts(loop) << " of " << n << '\n';
    std::cout << "sorted sizes:   " << mispredicts(in_order) << " of " << n << '\n';
    std::cout << "shuffled sizes: " << mispredicts(shuffled) << " of " << n << '\n';
    return 0;
}

