int mispredicts_history(const std::vector<bool>& outcomes) {
    int state[2] = {2, 2};
    bool last = false;
    int wrong = 0;
    for (bool taken : outcomes) {
        int& s = state[last];
        if ((s >= 2) != taken) {
            ++wrong;
        }
        if (taken && s < 3) {
            ++s;
        } else if (!taken && s > 0) {
            --s;
        }
        last = taken;
    }
    return wrong;
}

int main() {
    std::string history;
    std::cin >> history;
    std::vector<bool> outcomes;
    for (char c : history) {
        outcomes.push_back(c == 'T');
